gQC(){return"\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd"},
gtC(){return"\u05de\u05e9\u05e4\u05d7\u05d5\u05ea"},
gnI(){return"\u05de\u05d8\u05e4\u05dc\u05d5\u05ea"},
gAa(){return"\u05d2\u05d9\u05e9\u05d4"},
gKp(){return"\u05d7\u05e1\u05d5\u05de\u05d9\u05dd \u05d1\u05dc\u05d1\u05d3"},
