gNY(){return"\u05d0\u05d6\u05d5\u05e8 1 (\u05ea\u05dc \u05d0\u05d1\u05d9\u05d1)"},
gNZ(){return"\u05d0\u05d6\u05d5\u05e8 2 (\u05de\u05e8\u05db\u05d6)"},
gO_(){return"\u05d0\u05d6\u05d5\u05e8 3 (\u05e4\u05e8\u05d9\u05e4\u05e8\u05d9\u05d4)"},
gO0(){return"\u05d1\u05d7\u05e8\u05d5 \u05ea\u05d5\u05e6\u05d0\u05d4"},
gO1(){return"\u05d1\u05d7\u05e8\u05d5 \u05d0\u05d6\u05d5\u05e8"},
gO2(){return"\u05d6\u05d5 \u05ea\u05d5\u05e6\u05d0\u05d4 \u05dc\u05d2\u05d1\u05d9 \u05d0\u05d6\u05d5\u05e8 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05dc\u05d1\u05d3. \u05d0\u05e9\u05e8\u05d4, \u05d6\u05de\u05d9\u05e0\u05d5\u05ea, \u05de\u05e1\u05dc\u05d5\u05dc \u05d5\u05d2\u05d9\u05e9\u05d4 \u05e0\u05d1\u05d3\u05e7\u05d9\u05dd \u05d1\u05e0\u05e4\u05e8\u05d3, \u05d5\u05d4\u05e6\u05d5\u05d5\u05ea \u05d0\u05d9\u05e0\u05d5 \u05e0\u05d5\u05ea\u05df \u05d4\u05d9\u05ea\u05e8 \u05d4\u05e2\u05e1\u05e7\u05d4."},
O5(a){return"\u05d0\u05d6\u05d5\u05e8 \u05d1\u05de\u05e1\u05de\u05da: "+a},
gBg(){return"\u05d0\u05d6\u05d5\u05e8 \u05d7\u05e1\u05e8"},
gO8(){return"\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05d9\u05e9\u05d9\u05d5\u05df \u05dc\u05d0 \u05e0\u05e7\u05e8\u05d0 \u05de\u05d4\u05de\u05e1\u05de\u05da. \u05d0\u05d9\u05e9\u05d5\u05e8 \u05d4\u05ea\u05d5\u05e7\u05e3 \u05dc\u05e4\u05d9 \u05d4\u05de\u05e1\u05de\u05da \u05d0\u05d9\u05e0\u05d5 \u05de\u05d0\u05de\u05ea \u05d0\u05d6\u05d5\u05e8: \u05d4\u05e7\u05e9\u05e8 \u05d9\u05d9\u05e9\u05d0\u05e8 \u05e0\u05e2\u05d5\u05dc \u05e2\u05d3 \u05d1\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d6\u05d5\u05e8."},
gO9(){return"\u05ea\u05d5\u05e6\u05d0\u05d4"},
gOa(){return"\u05db\u05ea\u05d1\u05d5 \u05de\u05d4 \u05e0\u05d1\u05d3\u05e7 \u05d5\u05d1\u05d0\u05d9\u05d6\u05d4 \u05de\u05e7\u05d5\u05e8. \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05e0\u05e8\u05e9\u05de\u05ea \u05d1\u05d9\u05d5\u05de\u05df \u05e2\u05dd \u05e9\u05de\u05db\u05dd \u05d5\u05d4\u05e9\u05e2\u05d4."},
gOb(){return"\u05ea\u05d9\u05e2\u05d5\u05d3 \u05ea\u05d5\u05e6\u05d0\u05d4"},
gOc(){return"\u05de\u05ea\u05e2\u05d3\u05d9\u05dd \u05e8\u05e7 \u05de\u05d4 \u05e9\u05e0\u05de\u05e6\u05d0 \u05d1\u05de\u05e7\u05d5\u05e8 \u05de\u05d5\u05e8\u05e9\u05d4. \u05d0\u05d9\u05df \u05db\u05d0\u05df \u05de\u05ea\u05df \u05d4\u05d9\u05ea\u05e8."},
gOd(){return"\u05ea\u05d9\u05e2\u05d5\u05d3 \u05ea\u05d5\u05e6\u05d0\u05ea \u05d4\u05d1\u05d9\u05e8\u05d5\u05e8"},
gBh(){return"\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05ea\u05d5\u05e2\u05d3\u05d4"},
gOe(){return"\u05d0\u05d6\u05d5\u05e8 \u05e8\u05e9\u05d5\u05dd"},
gOf(){return"\u05d0\u05d6\u05d5\u05e8 1 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d9\u05d9\u05e9\u05d5\u05d1\u05d9\u05dd \u05d1\u05d0\u05d6\u05d5\u05e8\u05d9\u05dd 1\u20133, \u05d0\u05d6\u05d5\u05e8 2 \u05dc\u05d0\u05d6\u05d5\u05e8\u05d9\u05dd 2\u20133, \u05d5\u05d0\u05d6\u05d5\u05e8 3 \u05e8\u05e7 \u05dc\u05d0\u05d6\u05d5\u05e8 3. \u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05d9\u05e9\u05d9\u05d5\u05df \u05e0\u05d1\u05d3\u05e7 \u05de\u05d5\u05dc \u05d9\u05d9\u05e9\u05d5\u05d1 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc, \u05dc\u05d0 \u05de\u05d5\u05dc \u05e2\u05d9\u05e8 \u05d4\u05de\u05d2\u05d5\u05e8\u05d9\u05dd \u05e9\u05dc \u05d4\u05de\u05d8\u05e4\u05dc\u05ea."},
gOg(){return"\u05d4\u05d9\u05e7\u05e3"},
gOh(){return"\u05f4\u05de\u05d9\u05d3\u05e2 \u05de\u05e7\u05d5\u05d5\u05df \u05dc\u05de\u05e2\u05e1\u05d9\u05e7\u05d9\u05dd\u05f4 \u05e2\u05e9\u05d5\u05d9 \u05dc\u05d4\u05e6\u05d9\u05d2 \u05d0\u05ea \u05e1\u05d5\u05d2 \u05d4\u05d0\u05e9\u05e8\u05d4 \u05d5\u05e2\u05e0\u05e3 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4, \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05e9\u05d5\u05dd, \u05d4\u05de\u05e2\u05e1\u05d9\u05e7 \u05d5\u05d4\u05dc\u05e9\u05db\u05d4, \u05d5\u05ea\u05d0\u05e8\u05d9\u05da \u05d5\u05e1\u05d9\u05d1\u05ea \u05e1\u05d9\u05d5\u05dd \u05d4\u05e2\u05e1\u05e7\u05d4 \u05d0\u05dd \u05e0\u05e8\u05e9\u05de\u05d5. \u05d0\u05d9\u05df \u05d7\u05d9\u05d1\u05d5\u05e8 \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9 \u05dc\u05e9\u05d9\u05e8\u05d5\u05ea: \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d1\u05d5 \u05d9\u05d3\u05e0\u05d9\u05ea \u05d5\u05de\u05ea\u05e2\u05d3\u05d9\u05dd \u05db\u05d0\u05df."},
gtD(){return"\u05de\u05e7\u05d5\u05e8"},
gOi(){return"\u05d0\u05d9\u05e4\u05d4 \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd"},
gBi(){return"\u05d1\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d6\u05d5\u05e8"},
