gLL(){return"\u05de\u05d6\u05d4\u05d4 \u05d4\u05de\u05e9\u05e4\u05d7\u05d4"},
gLM(){return"\u05e0\u05d3\u05e8\u05e9 \u05de\u05d6\u05d4\u05d4 \u05de\u05e9\u05e4\u05d7\u05d4"},
gAL(){return"\u05de\u05e1\u05dc\u05d5\u05dc \u05d4\u05e2\u05e1\u05e7\u05d4"},
gAM(){return"\u05d0\u05d6\u05d5\u05e8 \u05e2\u05d1\u05d5\u05d3\u05d4"},
gAP(){return"\u05e9\u05de\u05d9\u05e8\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8"},
gAQ(){return"\u05d0\u05d6\u05d5\u05e8 \u05e8\u05e9\u05d5\u05dd \u05e9\u05dc \u05d4\u05de\u05d8\u05e4\u05dc\u05ea"},
Mj(a){return"\u05d2\u05e8\u05d4 \u05d1: "+a},
gMU(){return"\u05d4\u05e2\u05e8\u05d4"},
gMV(){return"\u05d4\u05e2\u05e8\u05d4 (\u05dc\u05d0 \u05d7\u05d5\u05d1\u05d4)"},
gN2(){return"\u05e0\u05d1\u05d3\u05e7 \u05e2\u05d1\u05d5\u05e8 \u05d4\u05de\u05e9\u05e4\u05d7\u05d4 \u05d4\u05d6\u05d5: \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05ea\u05e7\u05d3\u05dd \u05d1\u05de\u05e1\u05dc\u05d5\u05dc \u05d4\u05d6\u05d4. \u05e9\u05d0\u05e8 \u05d4\u05ea\u05e0\u05d0\u05d9\u05dd \u05e0\u05d1\u05d3\u05e7\u05d9\u05dd \u05d1\u05e0\u05e4\u05e8\u05d3."},
gO3(){return"\u05d1\u05d9\u05e8\u05d5\u05e8 \u05de\u05d5\u05e8\u05e9\u05d4"},
gO4(){return"\u05de\u05d4\u05de\u05e1\u05de\u05da"},
gO6(){return"\u05e2\u05d9\u05e8 \u05de\u05d2\u05d5\u05e8\u05d9\u05dd"},
gO7(){return"\u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05e9\u05d5\u05dd \u05d0\u05d9\u05e0\u05d5 \u05e0\u05e7\u05d1\u05e2 \u05dc\u05e4\u05d9 \u05d4\u05e2\u05e8\u05d9\u05dd \u05e9\u05d4\u05de\u05d8\u05e4\u05dc\u05ea \u05d1\u05d7\u05e8\u05d4."},
gOk(){return"\u05d0\u05d5\u05de\u05ea \u05d1"},
gOl(){return"\u05d0\u05d5\u05de\u05ea \u05d1\u05e2\u05d1\u05e8"},
gOm(){return"\u05e2\u05e8\u05d9\u05dd \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4"},
gP4(){return"\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05ea\u05d1\u05d5\u05d8\u05dc \u05d5\u05d4\u05e0\u05e2\u05d9\u05dc\u05d5\u05ea \u05d9\u05d7\u05d5\u05e9\u05d1\u05d5 \u05de\u05d7\u05d3\u05e9 \u05de\u05d9\u05d3. \u05db\u05ea\u05d1\u05d5 \u05dc\u05de\u05d4."},
gBv(){return"\u05d1\u05d9\u05d8\u05d5\u05dc \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4"},
gP5(){return"\u05d1\u05d9\u05d8\u05d5\u05dc \u05ea\u05d5\u05e6\u05d0\u05d4 \u05e9\u05ea\u05d5\u05e2\u05d3\u05d4"},
gBx(){return"\u05dc\u05db\u05dc \u05d4\u05de\u05e9\u05e4\u05d7\u05d5\u05ea"},
Pe(a){return"\u05de\u05e9\u05e4\u05d7\u05d4 "+a},
gPf(){return"\u05dc\u05de\u05e9\u05e4\u05d7\u05d4 \u05d0\u05d7\u05ea"},
gPO(){return"\u05db\u05ea\u05d1\u05d5 \u05d0\u05ea \u05d4\u05de\u05e7\u05d5\u05e8 (\u05dc\u05e4\u05d7\u05d5\u05ea 3 \u05ea\u05d5\u05d5\u05d9\u05dd)"},
gQH(){return"B/1"},
