Nm(a){return"\u0420\u0430\u043d\u0435\u0435 \u043e\u0434\u043e\u0431\u0440\u0435\u043d\u043d\u0430\u044f \u0432\u0438\u0437\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0434\u043e "+a},
