gOd(){return"\u0417\u0430\u043f\u0438\u0441\u044c \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438"},
gBh(){return"\u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0437\u0430\u043f\u0438\u0441\u0430\u043d"},
gOe(){return"\u0417\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0440\u0435\u0433\u0438\u043e\u043d"},
gOf(){return"\u0420\u0435\u0433\u0438\u043e\u043d 1 \u043f\u043e\u0434\u0445\u043e\u0434\u0438\u0442 \u0434\u043b\u044f \u043d\u0430\u0441\u0435\u043b\u0451\u043d\u043d\u044b\u0445 \u043f\u0443\u043d\u043a\u0442\u043e\u0432 \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0430\u0445 1\u20133, \u0440\u0435\u0433\u0438\u043e\u043d 2 \u2014 \u0434\u043b\u044f 2\u20133, \u0440\u0435\u0433\u0438\u043e\u043d 3 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f 3. \u0420\u0435\u0433\u0438\u043e\u043d \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438 \u0441\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u0441 \u043c\u0435\u0441\u0442\u043e\u043c \u0443\u0445\u043e\u0434\u0430, \u0430 \u043d\u0435 \u0441 \u0433\u043e\u0440\u043e\u0434\u043e\u043c \u043f\u0440\u043e\u0436\u0438\u0432\u0430\u043d\u0438\u044f \u0441\u0438\u0434\u0435\u043b\u043a\u0438."},
gOg(){return"\u041e\u0445\u0432\u0430\u0442"},
gOh(){return"\xab\u041e\u043d\u043b\u0430\u0439\u043d-\u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f \u0434\u043b\u044f \u0440\u0430\u0431\u043e\u0442\u043e\u0434\u0430\u0442\u0435\u043b\u0435\u0439\xbb \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0442\u044c \u0442\u0438\u043f \u0432\u0438\u0437\u044b \u0438 \u043e\u0442\u0440\u0430\u0441\u043b\u044c, \u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0440\u0435\u0433\u0438\u043e\u043d, \u0440\u0430\u0431\u043e\u0442\u043e\u0434\u0430\u0442\u0435\u043b\u044f \u0438 \u0431\u044e\u0440\u043e, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0434\u0430\u0442\u0443 \u0438 \u043f\u0440\u0438\u0447\u0438\u043d\u0443 \u043e\u043a\u043e\u043d\u0447\u0430\u043d\u0438\u044f \u0440\u0430\u0431\u043e\u0442\u044b, \u0435\u0441\u043b\u0438 \u043e\u043d\u0438 \u0443\u043a\u0430\u0437\u0430\u043d\u044b. \u0410\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0441\u0432\u044f\u0437\u0438 \u0441 \u0441\u0435\u0440\u0432\u0438\u0441\u043e\u043c \u043d\u0435\u0442: \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0439\u0442\u0435 \u0432\u0440\u0443\u0447\u043d\u0443\u044e \u0438 \u0437\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0439\u0442\u0435 \u0437\u0434\u0435\u0441\u044c."},
gtD(){return"\u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a"},
gOi(){return"\u0413\u0434\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0442\u044c"},
gBi(){return"\u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0440\u0435\u0433\u0438\u043e\u043d\u0430"},
gOj(){return"\u0414\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0434\u043e (\u0435\u0441\u043b\u0438 \u0443\u043a\u0430\u0437\u0430\u043d\u043e)"},
gOn(){return"\u041d\u0435\u0442 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0445 \u043f\u0440\u043e\u0432\u0435\u0440\u043e\u043a \u0440\u0435\u0433\u0438\u043e\u043d\u0430"},
gOo(){return"\u0421\u0438\u0434\u0435\u043b\u043a\u0438, \u0443 \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0440\u0435\u0433\u0438\u043e\u043d \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438 \u043d\u0435 \u0443\u043a\u0430\u0437\u0430\u043d \u0438\u043b\u0438 \u043d\u0435 \u043f\u043e\u0434\u0445\u043e\u0434\u0438\u0442 \u043a \u043c\u0435\u0441\u0442\u0443 \u0443\u0445\u043e\u0434\u0430. \u041f\u043e\u043a\u0430 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043d\u0435 \u0437\u0430\u043f\u0438\u0441\u0430\u043d, \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0430 \u043c\u043e\u0436\u0435\u0442 \u043e\u0442\u043e\u0431\u0440\u0430\u0436\u0430\u0442\u044c\u0441\u044f, \u043d\u043e \u043a\u043e\u043d\u0442\u0430\u043a\u0442 \u0438 \u043e\u043f\u043b\u0430\u0442\u0430 \u0437\u0430\u043a\u0440\u044b\u0442\u044b. \u0421\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a\u0438 \u0437\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u044e\u0442 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0438 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0438 \u043d\u0435 \u0432\u044b\u0434\u0430\u044e\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043d\u0430 \u0442\u0440\u0443\u0434\u043e\u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e."},
gwp(){return"\u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0440\u0430\u0431\u043e\u0447\u0435\u0433\u043e \u0440\u0435\u0433\u0438\u043e\u043d\u0430"},
Op(a){return"\u041e\u0436\u0438\u0434\u0430\u044e\u0442 \xb7 "+a},
gPL(){return"\u041e\u043d\u043b\u0430\u0439\u043d-\u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f \u0434\u043b\u044f \u0440\u0430\u0431\u043e\u0442\u043e\u0434\u0430\u0442\u0435\u043b\u0435\u0439"},
gQm(){return"\u041a \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0435 \u0440\u0435\u0433\u0438\u043e\u043d\u0430"},
gQq(){return"\u0422\u0438\u043f \u043d\u0435 \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d"},
gQE(){return"\u0412 \u043e\u0447\u0435\u0440\u0435\u0434\u0438 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043d\u0435 \u043e\u0434\u043e\u0431\u0440\u0438\u043b\u0430: \u043d\u0435\u0447\u0438\u0442\u0430\u0435\u043c\u044b\u0435, \u0441 \u0434\u0440\u0443\u0433\u043e\u0439 \u0438\u043b\u0438 \u0438\u0441\u0442\u0451\u043a\u0448\u0435\u0439 \u0434\u0430\u0442\u043e\u0439, \u0441 \u043d\u0435\u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u044b\u043c\u0438 \u0442\u0438\u043f\u043e\u043c \u0438\u043b\u0438 \u043e\u0442\u0440\u0430\u0441\u043b\u044c\u044e, \u0438\u043b\u0438 \u043a\u043e\u0433\u0434\u0430 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0447\u0442\u0435\u043d\u0438\u044f \u0435\u0449\u0451 \u043d\u0435\u0442. \u0427\u0451\u0442\u043a\u0438\u0439 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u0441 \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0449\u0435\u0439 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0439 \u0434\u0430\u0442\u043e\u0439 \u043e\u0434\u043e\u0431\u0440\u044f\u0435\u0442\u0441\u044f \u0431\u0435\u0437 \u0440\u0443\u0447\u043d\u043e\u0439 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438."},
gJD(){return"\u0417\u0430\u043f\u0438\u0441\u0430\u043d \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438"},
